import { Scene, SVG, SVGPath, VectorTransform, Rate } from "retiam";

const scene = new Scene({ canvas });

// 1. Ingest full hierarchical SVG with preserved layers
const icon = new SVG(`
    <svg viewBox="0 0 100 100">
        <circle cx="50" cy="50" r="40" fill="#3b82f6" />
        <path d="M30 50 L45 65 L70 35" stroke="#ffffff" stroke-width="8" fill="none" stroke-linecap="round"/>
    </svg>
`, { ignoreSvgDefaults: false });

icon.transform.scale = 0.08;
scene.add(icon);

// 2. Morph between two SVGs using automatic equalization
const checkmark = new SVGPath("M30 50 L45 65 L70 35", { stroke_width: 0.1 });
const cross = new SVGPath("M30 30 L70 70 M70 30 L30 70", { stroke_width: 0.1 });

scene.add(checkmark);
await scene.play(new VectorTransform(checkmark, cross, {
    duration: 1200,
    rate_func: Rate.easeInOutCubic()
}));
